# reuse g, generate seeds only within bounding boxes of 3 rectangles
boxes=[(2,9,3,10),(0,9,13,24),(12,15,13,21)]
seeds2=[(r,c) for r in range(R) for c in range(C) if g[r][c]==2 and any(r0<=r<=r1 and c0<=c<=c1 for r0,r1,c0,c1 in boxes)]
out2=[row[:] for row in g]
for r,c in seeds2:
 for rr in range(max(0,r-1),min(R,r+2)):
  for cc in range(max(0,c-1),min(C,c+2)):
   if out2[rr][cc]!=2: out2[rr][cc]=1
print(seeds2)
print('\n'.join(' '.join(map(str,row)) for row in out2))
